int main(){std::cout<<std::unitbuf;using namespace aether;using namespace aether::win;int argc=0;auto argv=CommandLineToArgvW(GetCommandLineW(),&argc);if(argc==3&&wcscmp(argv[1],L"--list")==0){auto text=listDirectoryWire(argv[2]);LocalFree(argv);DWORD written=0;return WriteFile(GetStdHandle(STD_OUTPUT_HANDLE),text.data(),static_cast<DWORD>(text.size()),&written,nullptr)?0:1;}LocalFree(argv);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);winrt::init_apartment(winrt::apartment_type::single_threaded);int checks=0;auto check=[&](bool ok,const char* name){if(!ok)throw std::runtime_error(name);++checks;std::cout<<"PASS "<<name<<'\n';};auto directory=executablePath().parent_path()/L"test-profiles"/(L"integration-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));std::filesystem::create_directories(directory);setConfigDirectory(directory);std::wstring registry=L"Software\\AetherUI\\Tests\\Integration-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64());HKEY key{};try{check(RegCreateKeyExW(HKEY_CURRENT_USER,registry.c_str(),0,nullptr,0,KEY_ALL_ACCESS,nullptr,&key,nullptr)==ERROR_SUCCESS,"owned registry test key");auto set=[&](const wchar_t* name,DWORD value){return RegSetValueExW(key,name,0,REG_DWORD,reinterpret_cast<BYTE*>(&value),sizeof(value))==ERROR_SUCCESS;};auto get=[&](const wchar_t* name)->DWORD{DWORD value=0,size=sizeof(value);if(RegQueryValueExW(key,name,nullptr,nullptr,reinterpret_cast<BYTE*>(&value),&size)!=ERROR_SUCCESS)return 0xFFFFFFFFu;return value;};check(set(L"Value",7)&&set(L"Unrelated",91),"test values initialized");{Handle event(CreateEventW(nullptr,TRUE,FALSE,nullptr));check(event&&RegNotifyChangeKeyValue(key,FALSE,REG_NOTIFY_CHANGE_LAST_SET,event.value,TRUE)==ERROR_SUCCESS,"owned registry change notification armed");RegistryThemeJournal same(directory/L"same-values.txt",{{registry,L"Value"}});std::string error;check(same.apply({{registry,L"Value",7}},&error)&&WaitForSingleObject(event.value,100)==WAIT_TIMEOUT,"unchanged theme values do not generate registry writes");}{RegistryThemeJournal journal(directory/L"journal.txt",{{registry,L"Value"},{registry,L"Missing"}});std::string error;check(journal.apply({{registry,L"Value",23},{registry,L"Missing",1}},&error),"journaled opt-in values apply");check(get(L"Value")==23&&get(L"Missing")==1,"applied DWORDs observed");check(journal.restore(&error)&&get(L"Value")==7&&get(L"Missing")==0xFFFFFFFFu&&get(L"Unrelated")==91,"restore exact values/absence without touching unrelated data");check(journal.apply({{registry,L"Value",32}},&error),"second apply");check(set(L"Value",99)&&journal.restore(&error)&&get(L"Value")==99,"external edits preserved on Restore");check(!journal.apply({{L"Software\\Unapproved",L"Value",1}},&error),"journal denies unapproved paths");check(set(L"Value",17)&&journal.apply({{registry,L"Value",42}},&error),"durable restore fixture armed");}{RegistryThemeJournal recovered(directory/L"journal.txt",{{registry,L"Value"},{registry,L"Missing"}});std::string error;check(recovered.restore(&error)&&get(L"Value")==17,"restore survives owner recreation");}
 auto fragment=terminalFragment(preset(1),IntegrationOptions{},"C:\\Windows");auto object=winrt::Windows::Data::Json::JsonObject::Parse(wide(fragment));check(object.GetNamedArray(L"profiles").Size()==3&&object.GetNamedArray(L"schemes").Size()==1,"generated Terminal JSON parses natively");auto target=directory/L"fragments"/L"aether.json";std::filesystem::create_directories(target.parent_path());writeAtomic(target,"{\"original\":true}");{AppearanceBridge bridge(directory/L"profile",target);auto options=bridge.options();options.terminal=true;check(bridge.configure(options,preset(1)),"Terminal fragment install");check(readText(target).find("Aether PowerShell")!=std::string::npos,"named profile added to owned fragment");options.terminal=false;check(bridge.configure(options,preset(1))&&readText(target)=="{\"original\":true}","original Terminal fragment restored exactly");options.terminal=true;check(bridge.configure(options,preset(1)),"Terminal fragment re-enabled");std::filesystem::create_directories(target.parent_path());writeAtomic(target,"{\"external\":true}");options.terminal=false;check(!bridge.configure(options,preset(1))&&readText(target)=="{\"external\":true}","external fragment edits preserved");}
 auto files=directory/L"files";std::filesystem::create_directories(files/L"folder");writeAtomic(files/L"résumé.txt","example");auto result=parseDirectoryWire(listDirectoryWire(files.wstring()));check(result.items.size()==2&&result.error.empty(),"local listing includes Unicode files and directories");check(!localDirectory(L"\\\\server\\share")&&!localDirectory(L"C:\\*.txt"),"UNC and wildcard requests rejected");check(!parseDirectoryWire("AetherFiles1\n\"\" 0\n\"../evil\" 0 0 0\n").error.empty(),"listing rejects path-bearing filenames");auto quoted=quoteArgument(L"C:\\with space\\");check(quoted==L"\"C:\\with space\\\\\"","Windows argument quoting preserves trailing separators");HWND owner=CreateWindowExW(0,L"STATIC",L"Aether integration test",0,0,0,1,1,HWND_MESSAGE,nullptr,GetModuleHandleW(nullptr),nullptr);check(owner!=nullptr,"owned message target created");DirectoryQuery query;std::wstring error;check(query.start(owner,files.wstring(),&error),"isolated folder worker starts");auto until=GetTickCount64()+5000;FileListing async;while(GetTickCount64()<until){MSG m{};bool ready=false;while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){if(m.message==FilesReadyMessage&&m.wParam==query.generation())ready=true;else DispatchMessageW(&m);}if(ready){async=query.take();break;}Sleep(10);}query.stop();check(async.items.size()==2&&async.error.empty(),"isolated folder worker returns bounded result and exits");
 wchar_t system[32768]{};GetSystemDirectoryW(system,32768);auto cmd=quoteArgument((std::filesystem::path(system)/L"cmd.exe").wstring());PtySession session;check(session.start(owner,cmd+L" /d /q /c \"echo AETHER_CONPTY_OK\"",files.wstring(),80,24,&error),"real ConPTY starts owned shell");std::string output;until=GetTickCount64()+5000;while(GetTickCount64()<until&&output.find("AETHER_CONPTY_OK")==output.npos){output+=session.takeOutput();Sleep(10);}check(output.find("AETHER_CONPTY_OK")!=output.npos,"real shell output received through VT pipe");auto stopped=GetTickCount64();session.stop();check(GetTickCount64()-stopped<3000,"ConPTY cleanup bounded");check(session.start(owner,cmd+L" /d /q /c \"set /p AETHER_TEST= & if defined AETHER_TEST echo AETHER_INPUT_EXECUTED\"",files.wstring(),80,24,&error),"interactive ConPTY starts");check(session.write("hello\r"),"input enqueued without blocking UI");output.clear();until=GetTickCount64()+5000;while(GetTickCount64()<until&&output.find("AETHER_INPUT_EXECUTED")==output.npos){output+=session.takeOutput();Sleep(10);}check(output.find("AETHER_INPUT_EXECUTED")!=output.npos,"shell consumes input and executes conditional output");check(session.resize(110,30),"pseudoconsole resize");session.stop();check(session.start(owner,cmd+L" /d /q /c \"for /L %i in (1,1,200000) do @echo AETHER_PRESSURE_%i\"",files.wstring(),80,24,&error),"output pressure fixture starts");Handle held(OpenProcess(SYNCHRONIZE,FALSE,session.pid()));Sleep(80);stopped=GetTickCount64();session.stop();check(GetTickCount64()-stopped<3000&&held&&WaitForSingleObject(held.value,1000)==WAIT_OBJECT_0,"close during output pressure drains pipes and ends only owned shell");DestroyWindow(owner);RegCloseKey(key);key=nullptr;RegDeleteTreeW(HKEY_CURRENT_USER,registry.c_str());std::cout<<checks<<" Windows integration checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';if(key)RegCloseKey(key);RegDeleteTreeW(HKEY_CURRENT_USER,registry.c_str());return 1;}}
